package com.renthouse.repair;
import com.renthouse.auth.*;import com.renthouse.common.api.PageResponse;import com.renthouse.common.exception.BusinessException;import com.renthouse.common.id.SnowflakeIdGenerator;import java.time.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class RepairService{private final JdbcTemplate j;private final SnowflakeIdGenerator ids;public RepairService(JdbcTemplate j,SnowflakeIdGenerator ids){this.j=j;this.ids=ids;}
 @Transactional public RepairView create(Create c){CurrentUser.requireRole(UserRole.TENANT);long tenant=CurrentUser.require().id();long[] x=j.query("SELECT unit_id,landlord_id FROM tenancy_contract WHERE id=? AND tenant_id=? AND status IN ('ACTIVE','CHECKOUT_PENDING')",r->r.next()?new long[]{r.getLong(1),r.getLong(2)}:null,c.contractId(),tenant);if(x==null)throw new BusinessException("REPAIR_CONTRACT_INVALID","仅有效合同可提交报修",HttpStatus.CONFLICT);long id=ids.nextId();LocalDateTime n=LocalDateTime.now();j.update("INSERT INTO repair_ticket(id,ticket_no,contract_id,unit_id,tenant_id,landlord_id,category,description,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?, 'PENDING',?,?)",id,"BX"+id,c.contractId(),x[0],tenant,x[1],c.category(),c.description(),n,n);return find(id);}
 public PageResponse<RepairView> list(int page,int size){AuthenticatedUser u=CurrentUser.require();page=Math.max(page,1);size=Math.min(Math.max(size,1),50);String c=u.role()==UserRole.LANDLORD?"landlord_id":"tenant_id";Long total=j.queryForObject("SELECT COUNT(*) FROM repair_ticket WHERE "+c+"=?",Long.class,u.id());return PageResponse.of(j.query("SELECT * FROM repair_ticket WHERE "+c+"=? ORDER BY created_at DESC LIMIT ? OFFSET ?",(r,n)->map(r),u.id(),size,(page-1)*size),total==null?0:total,page,size);}
 @Transactional public RepairView process(long id,Process c){CurrentUser.requireRole(UserRole.LANDLORD);RepairView v=find(id);if(Long.parseLong(v.landlordId())!=CurrentUser.require().id()||!("PENDING".equals(v.status())||"PROCESSING".equals(v.status())))throw new BusinessException("REPAIR_TRANSITION_INVALID","工单当前不可处理",HttpStatus.CONFLICT);j.update("UPDATE repair_ticket SET status='PROCESSING',assignee_name=?,assignee_mobile=?,handling_note=?,updated_at=? WHERE id=?",c.assigneeName(),c.assigneeMobile(),c.handlingNote(),LocalDateTime.now(),id);return find(id);}
 @Transactional public RepairView finish(long id,String note){CurrentUser.requireRole(UserRole.LANDLORD);RepairView v=find(id);if(Long.parseLong(v.landlordId())!=CurrentUser.require().id()||!"PROCESSING".equals(v.status()))throw new BusinessException("REPAIR_TRANSITION_INVALID","工单当前不可完成",HttpStatus.CONFLICT);LocalDateTime n=LocalDateTime.now();j.update("UPDATE repair_ticket SET status='AWAITING_CONFIRMATION',handling_note=?,completed_at=?,updated_at=? WHERE id=?",note,n,n,id);return find(id);}
 @Transactional public RepairView confirm(long id){CurrentUser.requireRole(UserRole.TENANT);RepairView v=find(id);if(Long.parseLong(v.tenantId())!=CurrentUser.require().id()||!"AWAITING_CONFIRMATION".equals(v.status()))throw new BusinessException("REPAIR_TRANSITION_INVALID","工单当前不可确认",HttpStatus.CONFLICT);j.update("UPDATE repair_ticket SET status='COMPLETED',updated_at=? WHERE id=?",LocalDateTime.now(),id);return find(id);}
 public RepairView find(long id){AuthenticatedUser u=CurrentUser.require();return j.query("SELECT * FROM repair_ticket WHERE id=? AND (tenant_id=? OR landlord_id=?)",r->{if(!r.next())throw new BusinessException("REPAIR_NOT_FOUND","报修单不存在",HttpStatus.NOT_FOUND);return map(r);},id,u.id(),u.id());}
 private RepairView map(java.sql.ResultSet r)throws java.sql.SQLException{return new RepairView(""+r.getLong("id"),r.getString("ticket_no"),""+r.getLong("contract_id"),""+r.getLong("tenant_id"),""+r.getLong("landlord_id"),r.getString("category"),r.getString("description"),r.getString("status"),r.getString("assignee_name"),r.getString("assignee_mobile"),r.getString("handling_note"),r.getTimestamp("completed_at")==null?null:r.getTimestamp("completed_at").toLocalDateTime(),r.getTimestamp("created_at").toLocalDateTime());}
 public record Create(long contractId,String category,String description){} public record Process(String assigneeName,String assigneeMobile,String handlingNote){}
}
